-- 90_VERIFY (read only). V1 = 2 rows: LOCAL_KRW 1, SAVE 2. PKG_DMF0020 and PKG_DMF0003 must not appear. V2 = VALID. V3 = 0 rows.
SELECT 'V1' AS CHK, NAME, TYPE, COUNT(*) AS MARKER_LINES FROM USER_SOURCE WHERE TEXT LIKE '%E20261102-RTFLATESTPRICE%' GROUP BY NAME, TYPE ORDER BY 2;
SELECT 'V2' AS CHK, OBJECT_NAME, OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME, 'YYYY-MM-DD HH24:MI:SS') AS LAST_DDL
  FROM USER_OBJECTS WHERE OBJECT_NAME IN ('PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW','PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE') AND OBJECT_TYPE IN ('PROCEDURE', 'PACKAGE BODY') ORDER BY 2, 3;
SELECT 'V3' AS CHK, NAME, TYPE, LINE, SUBSTR(TEXT, 1, 200) AS ERR FROM USER_ERRORS WHERE NAME IN ('PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW','PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE') ORDER BY 2, 3, SEQUENCE;
